import fs from 'node:fs';
import path from 'node:path';
import {performance} from 'node:perf_hooks';
import {createHash} from 'node:crypto';
import net from 'node:net';
const root='C:/Users/user/orca/workspaces/todays-math/exam-extraction-resume-20261008';const out=process.argv[2];const mode=process.argv[3]??'phases';const ticks:any[]=[];let networkCalls=0;net.Socket.prototype.connect=function(){networkCalls++;throw Error('Profile network disabled')} as any;
async function main(){const start=performance.now();const reg=await import(root+'/src/lib/examStudy/registry.ts');const importMs=performance.now()-start;const identity=await import(root+'/src/lib/examStudy/identity.ts');const curriculum=await import(root+'/src/lib/examStudy/curriculumEligibility.ts');const release=await import(root+'/src/lib/examStudy/releaseEligibility.ts');const req=await import(root+'/src/lib/examStudy/requirements.ts');const counts=(xs:any[],key:string)=>Object.fromEntries([...new Set(xs.map(x=>x[key]))].map(v=>[String(v),xs.filter(x=>x[key]===v).length]));
const measure=(name:string,fn:()=>any)=>{const t=performance.now();const value=fn();ticks.push({name,ms:performance.now()-t});return value};
let catalogs:any[]=[];let all:any[];let domainRows:any[]=[];let decomposition:any=null;
if(mode==='cold'){catalogs.push(measure('cold-first-M3-catalog',()=>reg.getExamStudyCatalog('중3')));all=reg.examStudyFamilies() as any[];catalogs.push(measure('warm-second-M3-catalog',()=>reg.getExamStudyCatalog('중3')))}else{
const adapters=await import(root+'/src/lib/examStudy/adapters.ts');const legacy=measure('cold-legacy-adapter-construction',()=>adapters.legacyStudyFamilies());all=measure('registry-assembly-and-initial-validation-after-legacy',()=>reg.examStudyFamilies()) as any[];
let enumerateCalls=0,enumerateMs=0;const observed=all.map(f=>({...f,paramDomain:f.paramDomain.kind==='finite'?{...f.paramDomain,enumerate:()=>{const t=performance.now();const e=f.paramDomain.enumerate();enumerateMs+=performance.now()-t;enumerateCalls++;return e}}:f.paramDomain}));measure('repeat-validation-observed-copies',()=>reg.validateStudyFamilies(observed));ticks.push({name:'enumeration-subcost-inside-validation',ms:enumerateMs,calls:enumerateCalls});
for(const f of all){if(f.paramDomain.kind!=='finite')continue;const t=performance.now();const entries=f.paramDomain.enumerate();const enumMs=performance.now()-t;const s=performance.now();const text=identity.stableStringify(entries);domainRows.push({id:f.id,course:f.course,size:f.paramDomain.size,entries:entries.length,enumerateMs:enumMs,stringifyMs:performance.now()-s,canonicalChars:text.length})}
const manifest=measure('manifest-direct-1',()=>reg.studyManifestVersion(all));measure('manifest-direct-2',()=>{const x=reg.studyManifestVersion(all);if(x!==manifest)throw Error('Manifest changed')});
const t=performance.now();const payload={engine:reg.EXAM_STUDY_ENGINE_VERSION,curriculumPolicy:curriculum.STUDY_CURRICULUM_POLICY_VERSION,releasePolicy:release.STUDY_RELEASE_POLICY_VERSION,requirements:req.STUDY_REQUIREMENTS,families:[...all].sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0).map(f=>({id:f.id,version:f.version,course:f.course,source:f.source,fulfills:f.fulfills,formats:f.formats,difficulties:f.difficulties,representation:f.representation,figureKinds:f.figureKinds,evidence:f.evidence,domain:f.paramDomain.kind==='finite'?{kind:'finite',size:f.paramDomain.size,parameters:f.paramDomain.enumerate()}:f.paramDomain}))};const projectionMs=performance.now()-t;const s=performance.now();const serialized=identity.stableStringify(payload);const stringifyMs=performance.now()-s;const h=performance.now();const digest=createHash('sha256').update(serialized).digest('hex');decomposition={projectionMs,stringifyMs,hashMs:performance.now()-h,canonicalChars:serialized.length,manifest:'exam-study-manifest-'+digest.slice(0,24),matchesActual:manifest==='exam-study-manifest-'+digest.slice(0,24)};if(!decomposition.matchesActual)throw Error('Projection not equivalent');
catalogs.push(measure('first-M3-catalog-after-registry',()=>reg.getExamStudyCatalog('중3')));catalogs.push(measure('warm-M3-catalog-repeat',()=>reg.getExamStudyCatalog('중3')));
}
const hashes=catalogs.map(c=>identity.sha256(c));if(new Set(hashes).size!==1)throw Error('Catalog outputs changed');const m3=all.filter(f=>f.course==='중3');const holds=all.filter(f=>curriculum.studyCurriculumHold(f)||release.studyReleaseHold(f)).map(f=>({id:f.id,course:f.course,curriculum:curriculum.studyCurriculumHold(f)?.status??null,release:release.studyReleaseHold(f)?.status??null}));const result={mode,node:process.version,importMs,ticks,totalMs:performance.now()-start,registry:{families:all.length,byCourse:counts(all,'course'),bySource:counts(all,'source'),finiteFamilies:all.filter(f=>f.paramDomain.kind==='finite').length,sampledFamilies:all.filter(f=>f.paramDomain.kind==='sampled').length,totalDeclaredFiniteSize:all.reduce((s,f)=>s+(f.paramDomain.kind==='finite'?f.paramDomain.size:0),0)},m3:{registered:m3.length,catalog:catalogs[0].families.length,profiles:catalogs[0].profiles.length,formats:[...new Set(catalogs[0].families.flatMap((f:any)=>f.formats))]},engineVersion:reg.EXAM_STUDY_ENGINE_VERSION,curriculumPolicy:curriculum.STUDY_CURRICULUM_POLICY_VERSION,releasePolicy:release.STUDY_RELEASE_POLICY_VERSION,manifest:catalogs[0].manifestVersion,catalogSHA256:hashes,holds,decomposition,domainRows:domainRows.sort((a,b)=>b.stringifyMs+b.enumerateMs-a.stringifyMs-a.enumerateMs),memory:process.memoryUsage(),networkCalls};fs.writeFileSync(out,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({mode,importMs,ticks,totalMs:result.totalMs,families:all.length,manifest:result.manifest,catalogSHA256:hashes[0],decomposition,networkCalls}));}
main().catch(e=>{console.error(e);process.exitCode=1});
